const root = $json || {};

// Récupération tolérante selon la structure réelle du webhook
const body = root.body && typeof root.body === "object" ? root.body : root;
const query = root.query && typeof root.query === "object" ? root.query : {};
const params = root.params && typeof root.params === "object" ? root.params : {};

// Cherche dealId / URL dans plusieurs endroits possibles
const rawDealId =
  body.dealId ??
  query.dealId ??
  params.dealId ??
  "";

const rawUrl =
  body.hubspotUrl ??
  query.hubspotUrl ??
  params.hubspotUrl ??
  body.url ??
  query.url ??
  "";

const rawMode =
  body.mode ??
  query.mode ??
  params.mode ??
  "full";

let dealId = String(rawDealId || "").trim();
const hubspotUrl = String(rawUrl || "").trim();
let mode = String(rawMode || "full").trim().toLowerCase();

if (!["full", "summary"].includes(mode)) {
  mode = "full";
}

// Extraction depuis URL HubSpot
if (!dealId && hubspotUrl) {
  const match = hubspotUrl.match(/\/record\/0-3\/(\d+)/);
  if (match) {
    dealId = match[1];
  }
}

// Fallback plus tolérant
if (!dealId && hubspotUrl) {
  const matches = hubspotUrl.match(/\d{6,}/g);
  if (matches && matches.length > 0) {
    dealId = matches[matches.length - 1];
  }
}

// Debug utile
return [
  {
    json: {
      dealId: dealId || null,
      hubspotUrl: hubspotUrl || null,
      mode,
      debug_received_body: body
    }
  }
];

const results = $node["HTTP_Get_Deal_Companies"].json.results || [];

const companyId = results.length ? results[0].id : null;

return [
  {
    json: {
      companyId
    }
  }
];

const results = $node["HTTP_Get_Deal_Contacts"].json.results || [];

return results.map(r => ({
  json: {
    contactId: r.id
  }
}));

function toArray(v) {
  if (Array.isArray(v)) return v;
  if (v == null) return [];
  return [v];
}

function daysBetween(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  const now = new Date();
  return Math.floor((now - d) / (1000 * 60 * 60 * 24));
}

const dealNode = $node["HubSpot_Get_Deal"].json || {};
const companyNode = $node["HubSpot_Get_Company"].json || {};

let contacts = [];
try {
  contacts = $items("HubSpot_Get_Contact").map(item => item.json);
} catch (e) {
  contacts = [];
}

const deal = dealNode.properties || dealNode;
const company = companyNode.properties || companyNode;

const dealName = String(deal.dealname || "");
const stage = String(deal.dealstage || "");
const amount = Number(deal.amount || 0);
const createdAt = deal.createdate || deal.hs_createdate || null;
const lastModified = deal.hs_lastmodifieddate || deal.lastmodifieddate || null;
const description = String(deal.description || "").trim();

const companyName = String(company.name || "").trim();
const domain = String(company.domain || company.website || "").trim();

const contactCount = contacts.filter(c => {
  const p = c.properties || c;
  return p.email || p.firstname || p.lastname;
}).length;

const dealAgeDays = daysBetween(createdAt);
const daysSinceLastUpdate = daysBetween(lastModified);

let score = 100;
const strengths = [];
const risks = [];

// Contacts
if (contactCount === 0) {
  score -= 25;
  risks.push("No associated contact.");
} else if (contactCount === 1) {
  score -= 10;
  risks.push("Only one associated contact.");
} else {
  strengths.push("Multiple contacts associated.");
}

// Company
if (!companyName) {
  score -= 15;
  risks.push("No associated company.");
} else {
  strengths.push("Associated company found.");
}

// Recency
if (daysSinceLastUpdate === null) {
  score -= 10;
  risks.push("Last update date unavailable.");
} else if (daysSinceLastUpdate > 30) {
  score -= 20;
  risks.push(`Deal inactive for ${daysSinceLastUpdate} days.`);
} else if (daysSinceLastUpdate > 14) {
  score -= 10;
  risks.push(`Deal not updated for ${daysSinceLastUpdate} days.`);
} else {
  strengths.push("Recently updated deal.");
}

// Age
if (dealAgeDays !== null) {
  if (dealAgeDays > 180) {
    score -= 15;
    risks.push(`Old deal (${dealAgeDays} days).`);
  } else if (dealAgeDays > 90) {
    score -= 8;
    risks.push(`Aging deal (${dealAgeDays} days).`);
  } else {
    strengths.push("Deal age still healthy.");
  }
}

// Amount
if (amount > 0) {
  strengths.push("Amount is populated.");
} else {
  score -= 10;
  risks.push("Amount is missing or zero.");
}

// Description
if (!description) {
  score -= 5;
  risks.push("Deal description is empty.");
} else {
  strengths.push("Deal description exists.");
}

// Domain
if (!domain) {
  score -= 5;
  risks.push("Company domain/website missing.");
} else {
  strengths.push("Company domain/website available.");
}

score = Math.max(0, Math.min(100, score));

let status = "Healthy";
if (score < 75) status = "Watch";
if (score < 55) status = "At Risk";
if (score < 35) status = "Critical";

return [{
  json: {
    deal_health_score: score,
    deal_health_status: status,
    deal_health_strengths: strengths,
    deal_health_risks: risks,
    metrics: {
      deal_name: dealName,
      stage,
      amount,
      company_name: companyName,
      contact_count: contactCount,
      deal_age_days: dealAgeDays,
      days_since_last_update: daysSinceLastUpdate,
    }
  }
}];

const webhookNode = $node["Webhook"].json || {};
const body = webhookNode.body || {};

const dealNode = $node["HubSpot_Get_Deal"].json || {};
const companyNode = $node["HubSpot_Get_Company"].json || {};
const health = $node["Code_Compute_Deal_Health"].json || {};

let contacts = [];
try {
  contacts = $items("HubSpot_Get_Contact").map(item => item.json);
} catch (e) {
  contacts = [];
}

let notes = [];
try {
  const notesRes = $node["HTTP_Get_Deal_Notes"].json || {};
  notes = Array.isArray(notesRes.results) ? notesRes.results : [];
} catch (e) {
  notes = [];
}

const deal = dealNode.properties || dealNode;
const company = companyNode.properties || companyNode;
const emailContext = body.email_context || null;

function cleanText(value) {
  return String(value || "")
    .replace(/<[^>]*>/g, " ")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\u00A0/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function stripUrls(text) {
  return String(text || "").replace(/https?:\/\/\S+/gi, "[LINK]");
}

function stripQuotedReply(text) {
  let t = String(text || "");

  const patterns = [
    /\nOn .+ wrote:\s*$/is,
    /\nLe .+ a écrit\s*:\s*$/is,
    /\nEl .+ escribió:\s*$/is,
    /\nDe:\s.+$/is,
    /\nFrom:\s.+$/is,
    /\n-----Original Message-----.*$/is,
    /\n_{5,}.*$/is
  ];

  for (const pattern of patterns) {
    if (pattern.test(t)) {
      t = t.replace(pattern, "");
    }
  }

  return t;
}

function stripNoise(text) {
  let t = String(text || "");

  t = t.replace(/Powered by HubSpot.*$/gis, "");
  t = t.replace(/Is this email not relevant to you\?.*$/gis, "");
  t = t.replace(/Sent from my iPhone.*$/gis, "");
  t = t.replace(/Envoyé de mon iPhone.*$/gis, "");
  t = t.replace(/\[image:[^\]]*\]/gi, "[IMAGE]");
  t = t.replace(/\[cid:[^\]]*\]/gi, "[ATTACHMENT]");
  t = t.replace(/This email and any files transmitted with it are confidential.*$/gis, "");
  t = t.replace(/This email and any attachments may contain confidential information.*$/gis, "");
  t = t.replace(/Ce message et toutes ses pièces jointes peuvent contenir des informations confidentielles.*$/gis, "");
  t = t.replace(/En lo relativo a los Datos de Carácter Personal.*$/gis, "");

  return t;
}

function redactSensitive(text) {
  let t = String(text || "");

  t = t.replace(/(\bpassword\b|\bpw\b|\bpass\b)\s*[:=]\s*[^\s,;]+/gi, "$1: [REDACTED]");
  t = t.replace(/(\blogin\b|\busername\b)\s*[:=]\s*[^\s,;]+/gi, "$1: [REDACTED]");
  return t;
}

function compactEmailBody(value, max = 700) {
  let t = cleanText(value);
  t = stripQuotedReply(t);
  t = stripNoise(t);
  t = stripUrls(t);
  t = redactSensitive(t);
  t = cleanText(t);

  if (t.length > max) {
    t = t.slice(0, max) + "…";
  }

  return t;
}

function truncate(value, max = 1000) {
  const text = cleanText(value);
  return text.length > max ? text.slice(0, max) + "…" : text;
}

function safeList(arr, formatter) {
  return Array.isArray(arr) && arr.length ? arr.map(formatter).join("\n") : "- None";
}

const contactLines = contacts.length
  ? contacts.map(c => {
      const p = c.properties || c;
      const first = cleanText(p.firstname);
      const last = cleanText(p.lastname);
      const title = cleanText(p.jobtitle);
      const email = cleanText(p.email);
      return `- ${first} ${last} | ${title || "No title"} | ${email || "No email"}`.trim();
    }).join("\n")
  : "- No contacts found";

const notesLines = notes.length
  ? notes.map(n => {
      const p = n.properties || n;
      const noteBody = truncate(p.hs_note_body, 600);
      const ts = cleanText(p.hs_timestamp);
      return `- [${ts || "No timestamp"}] ${noteBody}`;
    }).join("\n\n")
  : "- No deal notes found";

const emailMetaBlock = emailContext
  ? [
      `- Emails returned: ${cleanText(emailContext.email_count_returned) || "0"}`,
      `- Last inbound: ${cleanText(emailContext.last_inbound_at) || "None"}`,
      `- Last outbound: ${cleanText(emailContext.last_outbound_at) || "None"}`,
      `- Last thread activity: ${cleanText(emailContext.last_thread_at) || "None"}`
    ].join("\n")
  : "- No recent email context provided";

const emailLines = emailContext && Array.isArray(emailContext.emails) && emailContext.emails.length
  ? emailContext.emails.map((e, i) => {
      const date = cleanText(e.date);
      const subject = cleanText(e.subject);
      const direction = cleanText(e.direction);
      const from = cleanText(e.from);
      const to = Array.isArray(e.to) ? e.to.map(cleanText).filter(Boolean).join(", ") : cleanText(e.to);
      const cc = Array.isArray(e.cc) ? e.cc.map(cleanText).filter(Boolean).join(", ") : cleanText(e.cc);
      const bodyClean = compactEmailBody(e.body_cleaned, 700);

      return [
        `Email ${i + 1}`,
        `- Date: ${date || "Unknown"}`,
        `- Direction: ${direction || "Unknown"}`,
        `- From: ${from || "Unknown"}`,
        `- To: ${to || "-"}`,
        `- Cc: ${cc || "-"}`,
        `- Subject: ${subject || "-"}`,
        `- Body: ${bodyClean || "-"}`
      ].join("\n");
    }).join("\n\n")
  : "- No recent emails found";


// ===== EMAIL SIGNALS ANALYSIS =====

let stakeholderSet = new Set();
let inboundCount = 0;
let outboundCount = 0;

if (emailContext && Array.isArray(emailContext.emails)) {
  emailContext.emails.forEach(e => {

    if (e.direction === "inbound") inboundCount++;
    if (e.direction === "outbound") outboundCount++;

    if (Array.isArray(e.to)) {
      e.to.forEach(x => stakeholderSet.add(x));
    }

    if (Array.isArray(e.cc)) {
      e.cc.forEach(x => stakeholderSet.add(x));
    }

    if (e.from) stakeholderSet.add(e.from);

  });
}

const stakeholders = Array.from(stakeholderSet)
  .filter(x => x && !String(x).toLowerCase().includes("@magrid.education"))
  .slice(0,5)
  .join(", ");

const conversationMaturity =
  inboundCount === 0
    ? "One-sided outreach"
    : inboundCount <= 2
    ? "Early engagement"
    : "Active conversation";

const responsiveness =
  inboundCount === 0
    ? "No response"
    : inboundCount < outboundCount
    ? "Moderate"
    : "Strong";

const emailSignalsSummary = `
Conversation maturity: ${conversationMaturity}
Stakeholder responsiveness: ${responsiveness}
External stakeholders detected: ${stakeholders || "None detected"}
Inbound messages: ${inboundCount}
Outbound messages: ${outboundCount}
`.trim();


const dealContext = `
DEAL
Name: ${cleanText(deal.dealname)}
Stage: ${cleanText(deal.dealstage)}
Pipeline: ${cleanText(deal.pipeline)}
Amount: ${cleanText(deal.amount)}
Close date: ${cleanText(deal.closedate)}
Created at: ${cleanText(deal.createdate)}
Last modified: ${cleanText(deal.hs_lastmodifieddate)}
Description: ${truncate(deal.description, 800)}

COMPANY
Name: ${cleanText(company.name)}
Domain: ${cleanText(company.domain)}
Website: ${cleanText(company.website)}
Country: ${cleanText(company.country)}
City: ${cleanText(company.city)}
Industry: ${cleanText(company.industry)}
Description: ${truncate(company.description, 800)}

CONTACTS
${contactLines}

DEAL HEALTH
Score: ${cleanText(health.deal_health_score)}
Status: ${cleanText(health.deal_health_status)}
Strengths:
${safeList(health.deal_health_strengths, x => `- ${cleanText(x)}`)}
Risks:
${safeList(health.deal_health_risks, x => `- ${cleanText(x)}`)}

DEAL NOTES
${notesLines}

EMAIL SIGNALS
${emailMetaBlock}

EMAIL SIGNALS SUMMARY
${emailSignalsSummary}

RECENT EMAILS
${emailLines}
`;

const aiPrompt = `
You are a senior B2G and institutional education sales strategist working for Magrid.

Your task is to produce a strategic reading of the deal below.

Return exactly these sections:

1. Executive Summary
2. Political / Institutional Reading
3. Stakeholder Hypothesis
4. Real Closing Probability
5. Main Risks
6. Strategic Next Moves
7. 30-Day Closing Plan
8. Suggested Follow-up Email

Rules:
- Formal, strategic and practical tone
- No invented facts
- If information is missing, state it clearly
- Adapt to ministries, NGOs, school groups, distributors and institutional buyers when relevant
- Use Deal Health as one signal, not as the only truth
- Use deal notes carefully when they contain useful buying signals, constraints, stakeholder clues, budget timing, or institutional process details
- Use recent emails as a core signal for relationship dynamics, responsiveness, stakeholder engagement, objections, implementation blockers, and momentum
- Distinguish clearly between operational trial/support activity and real commercial progression toward closing
- If email signals contradict optimistic CRM fields, state the risk explicitly
- Do not treat active email traffic alone as proof of commercial commitment
- Mention when the relationship appears active but mainly operational rather than commercial

Context:
${dealContext}
`;

return [{
  json: {
    deal_context: dealContext,
    ai_prompt: aiPrompt,
    deal_health_score: health.deal_health_score,
    deal_health_status: health.deal_health_status,
    email_context: emailContext,
    mode: body.mode || "strategy",
    record_type: "deal"
  }
}];
